<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {ShieldCheck,Search,RefreshCw,ArrowUpRight,History,X,Link as LinkIcon,ChevronLeft,ChevronRight,AlertTriangle,LockKeyhole,Clock,CheckCircle2,XCircle} from 'lucide-vue-next';
const statIcon:Record<string,any>={PENDING:Clock,DISPUTED:AlertTriangle,PASS:CheckCircle2,FAIL:XCircle};
const statTone:Record<string,string>={PENDING:'tone-amber',DISPUTED:'tone-rose',PASS:'tone-mint',FAIL:'tone-slate'};
import {api} from './api';
const props=defineProps<{courseId:number;userId:number;role:string;assignments:any[];focus?:{id:number;nonce:number}}>();const emit=defineEmits(['open-submission','changed']);
const names:Record<string,string>={PENDING:'待核验',DISPUTED:'有争议',PASS:'已通过',FAIL:'未通过'};const roles:Record<string,string>={TEACHER:'教师裁定',ASSISTANT:'助教核验',STUDENT:'同伴核验'};
const rows=ref<any[]>([]),counts=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),state=ref(''),relation=ref('ALL'),assignmentId=ref('0'),loading=ref(false),error=ref(''),status=ref('');const dialog=ref<HTMLDialogElement>(),detail=ref<any>(null),detailLoading=ref(false),detailError=ref(''),reason=ref(''),verdict=ref('PASS'),busy=ref(false),conflict=ref(false);let alive=true,generation=0,detailGeneration=0,debounce:ReturnType<typeof setTimeout>,returnFocus:HTMLElement|null=null;
const pages=computed(()=>Math.max(1,Math.ceil(total.value/20)));const teacher=computed(()=>props.role==='TEACHER');const count=(s:string)=>counts.value.find(x=>x.state===s)?.total||0;
function date(v:string){return new Date(v).toLocaleString('zh-CN',{hour12:false});}function safeUrl(v:string){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
async function load(){if(!alive)return;const g=++generation;loading.value=true;error.value='';try{const params=new URLSearchParams({q:q.value,state:state.value,relation:relation.value,assignmentId:assignmentId.value,page:String(page.value)});const r=await api(`/courses/${props.courseId}/evidence-workbench?${params}`);if(g!==generation)return;rows.value=r.items;counts.value=r.counts;total.value=r.total;if(page.value>pages.value){page.value=pages.value;await load();}}catch(e:any){if(g===generation)error.value=e.message;}finally{if(g===generation)loading.value=false;}}
function filter(){clearTimeout(debounce);page.value=1;void load();}function search(){clearTimeout(debounce);page.value=1;debounce=setTimeout(load,250);}
async function turnPage(delta:number){page.value+=delta;await load();window.scrollTo({top:0,behavior:'instant'});}
async function fetchDetail(id:number){if(!alive)return;const g=++detailGeneration;detailLoading.value=true;detailError.value='';try{const d=await api(`/evidence/${id}/review`);if(g!==detailGeneration)return;if(d.course_id!==props.courseId)throw Error('此证据不属于当前课程');detail.value=d;conflict.value=false;}catch(e:any){if(g===detailGeneration){detailError.value=e.message;detail.value=null;}}finally{if(g===detailGeneration)detailLoading.value=false;}}
async function open(id:number){if(dialog.value?.open&&!close())return;returnFocus=document.activeElement as HTMLElement;reason.value='';verdict.value='PASS';detail.value=null;conflict.value=false;await nextTick();dialog.value?.showModal();await fetchDetail(id);}
function close(){if(busy.value)return false;if(reason.value.trim()&&!confirm('离开将放弃本次尚未提交的判断依据，是否继续？'))return false;detailGeneration++;dialog.value?.close();reason.value='';detail.value=null;detailLoading.value=false;returnFocus?.focus();return true;}
async function refreshDetail(){if(!detail.value)return;const id=detail.value.id;await fetchDetail(id);status.value='已刷新证据与核验历史；你的判断依据仍保留，请重新核对。';}
async function submit(){if(!detail.value||busy.value||conflict.value||!detail.value.can_verify)return;const d=detail.value;if(teacher.value&&!confirm('确认提交教师裁定？历史记录将保留，且同伴不能再改判本条证据。'))return;busy.value=true;detailError.value='';try{await api(`/evidence/${d.id}/decisions`,'POST',{verdict:verdict.value,reason:reason.value,expectedCount:Number(d.record_count)});reason.value='';status.value=teacher.value?'教师裁定已记录。':'核验结果已记录；结论不一致时将转为争议。';await fetchDetail(d.id);await load();if(alive)emit('changed');}catch(e:any){detailError.value=e.message;conflict.value=e.status===409;if([403,422].includes(e.status)){conflict.value=true;}}finally{busy.value=false;}}
function openSubmission(){const d=detail.value;if(!d?.can_read_submission||!close())return;emit('open-submission',{id:d.submission_id,paragraphId:d.paragraph_id,review:teacher.value});}
function beforeUnload(e:BeforeUnloadEvent){if(reason.value.trim()||busy.value){e.preventDefault();e.returnValue='';}}
watch(()=>props.focus,f=>{if(f?.id)void open(f.id);});onMounted(()=>{void load();if(props.focus?.id)void open(props.focus.id);window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{alive=false;generation++;detailGeneration++;clearTimeout(debounce);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template><section class="page evidence-workbench"><div class="page-heading"><div><span class="eyebrow">来源与论断</span><h1>证据核验</h1><p>对照原始来源与引用段落，留下可追溯的判断依据。</p></div><button class="btn secondary" :disabled="loading" @click="load"><RefreshCw :size="16"/>刷新证据</button></div>
<div class="evidence-stats"><button v-for="s in ['PENDING','DISPUTED','PASS','FAIL']" :key="s" class="stat-card" :class="[statTone[s],{active:state===s}]" @click="state=state===s?'':s;filter()"><i class="stat-icon"><component :is="statIcon[s]" :size="17"/></i><span>{{ names[s] }}</span><strong>{{ count(s) }}</strong><small v-if="s==='DISPUTED'||s==='PENDING'">{{ s==='DISPUTED'?'等待教师裁定':'尚无核验结论' }}</small></button></div>
<p v-if="status" class="member-status" role="status">{{ status }}</p><p v-if="error" class="notice-error" role="alert">{{ error }}</p>
<div class="evidence-filter-bar"><label class="evidence-search"><Search :size="16"/><input v-model="q" maxlength="80" aria-label="搜索证据" placeholder="搜索来源、论断、作品或作者" @input="search"/></label><select v-model="state" aria-label="按核验状态筛选" @change="filter"><option value="">全部状态</option><option v-for="(n,k) in names" :key="k" :value="k">{{ n }}</option></select><select v-model="relation" aria-label="按核验关系筛选" @change="filter"><option value="ALL">全部证据</option><option value="TODO">我可核验</option><option value="DONE">我已核验</option><option value="MINE">我的证据</option></select><select v-model="assignmentId" aria-label="按作业筛选证据" @change="filter"><option value="0">全部作业</option><option v-for="a in assignments" :key="a.id" :value="String(a.id)">{{ a.title }}</option></select></div>
<div class="evidence-list" :aria-busy="loading"><article v-for="e in rows" :key="e.id" class="evidence-card" :data-evidence-id="e.id"><div class="card-top"><span class="source-label"><LinkIcon :size="17"/>{{ e.source_title }}</span><span class="badge" :class="e.state==='PASS'?'green':e.state==='FAIL'?'red':'orange'">{{ names[e.state] }}</span></div><h3>{{ e.claim_text }}</h3><blockquote>{{ e.excerpt }}</blockquote><p class="muted">{{ e.author_name }} · {{ e.title }} · v{{ e.version_no }}</p><p class="evidence-task-name">{{ e.assignment_title }}</p><div class="evidence-actions"><span class="muted evidence-record-count"><History :size="14"/>{{ e.record_count }} 条核验记录<span v-if="e.locked"><LockKeyhole :size="13"/>评分后冻结</span></span><button class="btn secondary" :disabled="loading" @click="open(e.id)"><ShieldCheck :size="16"/>{{ e.can_verify?(teacher?'核验 / 裁定':'核对这条证据'):'查看证据详情' }}</button></div><p v-if="!e.can_verify" class="evidence-blocked">{{ e.blocked_reason }}</p></article><div v-if="!loading&&!rows.length" class="card empty"><ShieldCheck :size="30"/><h2>没有匹配的证据</h2><p>可以调整筛选；只有挂载证据并提交后，才会进入核验列表。</p></div><p v-if="loading" class="empty-text">正在读取证据…</p></div>
<footer class="member-pagination"><span>{{ total }} 条匹配证据 · 第 {{ page }} / {{ pages }} 页</span><div><button class="btn secondary" :disabled="page<=1||loading" @click="turnPage(-1)"><ChevronLeft :size="14"/>上一页</button><button class="btn secondary" :disabled="page>=pages||loading" @click="turnPage(1)">下一页<ChevronRight :size="14"/></button></div></footer>
<Teleport to="body"><dialog ref="dialog" class="evidence-review-dialog" aria-labelledby="evidence-review-title" @cancel.prevent="close"><header><div><span class="eyebrow">来源、论断与记录</span><h2 id="evidence-review-title">证据核验详情</h2></div><button class="icon-btn" aria-label="关闭证据详情" :disabled="busy" @click="close"><X :size="20"/></button></header><div class="evidence-review-body"><p v-if="detailLoading" class="empty-text">正在读取证据详情…</p><p v-if="detailError" class="notice-error" role="alert">{{ detailError }}</p><template v-if="detail"><div class="evidence-detail-meta"><span class="badge" :class="detail.state==='PASS'?'green':detail.state==='FAIL'?'red':'orange'">{{ names[detail.state] }}</span><span>{{ detail.author_name }} · v{{ detail.version_no }}</span><button class="text-btn" :disabled="busy||detailLoading" @click="refreshDetail"><RefreshCw :size="14"/>刷新记录</button></div><h3>{{ detail.source_title }}</h3><a v-if="safeUrl(detail.source_url)" class="text-btn" :href="safeUrl(detail.source_url)" target="_blank" rel="noopener noreferrer">打开原始来源<ArrowUpRight :size="14"/></a><p v-else class="muted">未提供可打开的来源链接，请根据来源信息人工核对。</p><div class="evidence-comparison"><section><h4>来源摘录</h4><blockquote>{{ detail.excerpt }}</blockquote></section><section><h4>需要支持的论断</h4><p>{{ detail.claim_text }}</p></section><section><h4>引用处正文 · 提交时的段落</h4><p>{{ detail.paragraph_text || '此条未找到对应段落文字，请联系作者或教师核对。' }}</p><button v-if="detail.can_read_submission" class="text-btn" :disabled="busy" @click="openSubmission">{{ teacher?'返回教师评审并定位正文':'查看提交版本并定位正文' }}<ArrowUpRight :size="14"/></button><small v-else>此提交尚未向你开放全文，仅提供证据对应段落用于核验。</small></section></div>
<section class="evidence-history"><h3>核验历史 <span class="small-label">{{ detail.record_count }} 条</span></h3><article v-for="r in detail.records" :key="r.id"><div><strong>{{ r.verifier_name }}</strong><span class="badge" :class="r.verdict==='PASS'?'green':'red'">{{ r.verdict==='PASS'?'通过':'未通过' }}</span></div><small>{{ roles[r.verifier_role] || '历史记录 · 身份未留存' }} · {{ date(r.created_at) }}</small><p>{{ r.reason }}</p></article><p v-if="!detail.records.length" class="muted">尚无核验记录。</p></section>
<form v-if="detail.can_verify" class="evidence-decision-form" @submit.prevent="submit"><h3>{{ teacher?'提交教师裁定':'记录你的核验结论' }}</h3><p v-if="detail.state==='DISPUTED'" class="evidence-warning"><AlertTriangle :size="15"/>已有结论不一致，请先核对各方依据。</p><fieldset :disabled="busy||conflict||detailLoading"><label>核验结论<select v-model="verdict" aria-label="核验结论"><option value="PASS">通过：来源与论断支持关系成立</option><option value="FAIL">未通过：来源、引文或支持关系存在问题</option></select></label><label>对照材料与判断依据<textarea v-model="reason" required maxlength="2000" rows="4" placeholder="说明核对的材料、位置及支持或不支持的原因"/></label></fieldset><button class="btn primary" :disabled="busy||conflict||detailLoading">{{ busy?'正在保存…':teacher?'提交教师裁定':'提交核验结论' }}</button></form><p v-else class="evidence-readonly"><LockKeyhole :size="16"/>{{ detail.blocked_reason }}</p><p v-if="conflict" class="evidence-warning">请先点「刷新记录」核对最新状态。</p></template></div><footer><button class="btn secondary" :disabled="busy" @click="close">关闭详情</button></footer></dialog></Teleport>
</section></template>
